def iscube(a):
    if a == 0:
        return True
    abs_a = abs(a)
    low, high = 0, abs_a
    while low <= high:
        mid = (low + high) // 2
        cube = mid ** 3
        if cube == abs_a:
            return True
        elif cube < abs_a:
            low = mid + 1
        else:
            high = mid - 1
    return False
